def rob(nums):
    even = odd = 0
    for i, x in enumerate(nums):
        if i % 2: odd = max(even, odd + x)
        else: even = max(odd, even + x)
    return max(even, odd)

def word_break(s, wordDict):
    words = set(wordDict)
    n = len(s)
    dp = [False]*(n+1); dp[0] = True
    for i in range(1, n+1):
        for j in range(i):
            if dp[j] and s[j:i] in words:
                dp[i] = True; break
    return dp[n]

def word_break(s, wordDict):
    words = set(wordDict); L = max(map(len, words), default=0)
    n = len(s); dp = [False]*(n+1); dp[0] = True
    for i in range(1, n+1):
        for j in range(max(0, i-L), i):
            if dp[j] and s[j:i] in words:
                dp[i] = True; break
    return dp[n]

from collections import deque
def word_break(s, wordDict):
    words = set(wordDict); n = len(s)
    q = deque([0]); seen = {0}
    while q:
        i = q.popleft()
        if i == n: return True
        for w in words:
            if s.startswith(w, i) and i+len(w) not in seen:
                seen.add(i+len(w)); q.append(i+len(w))
    return False

def coin_change(coins, amount):
    INF = 10**9
    dp = [INF]*(amount+1); dp[0] = 0
    for a in range(1, amount+1):
        for c in coins:
            if a >= c:
                dp[a] = min(dp[a], dp[a-c] + 1)
    return dp[amount] if dp[amount] != INF else -1

from collections import deque
def coin_change(coins, amount):
    q = deque([(0, 0)]); seen = {0}
    while q:
        a, d = q.popleft()
        if a == amount: return d
        for c in coins:
            na = a + c
            if na <= amount and na not in seen:
                seen.add(na); q.append((na, d+1))
    return -1 if amount else 0

def length_of_lis(nums):
    dp = [1]*len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp, default=0)

from bisect import bisect_left
def length_of_lis(nums):
    tails = []
    for x in nums:
        i = bisect_left(tails, x)
        if i == len(tails): tails.append(x)
        else: tails[i] = x
    return len(tails)
